head.b:skin:
/* ============================================================
   YINYANGYO LEGACY BLOG // ORIGINAL BLOGGER ARCHIVE THEME
   Visual language: dark security lab / cyan terminal / glass cards
   ============================================================ */
:root{
  --bg:#050912;
  --bg-soft:#070d17;
  --panel:#080e18;
  --panel-2:#0b1321;
  --panel-3:#0e1727;
  --line:#1c2a40;
  --line-2:#263852;
  --text:#f5f7fb;
  --muted:#8ea2be;
  --muted-2:#6e849f;
  --green:#00e6b2;
  --green-dark:#007d61;
  --green-bg:#063e31;
  --blue:#46d7ff;
  --purple:#b177ff;
  --yellow:#ffd21a;
  --orange:#ff7a00;
  --shadow:0 18px 50px rgba(0,0,0,.34);
  --radius:16px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  background:
    radial-gradient(circle at 10% -10%,rgba(0,230,178,.045),transparent 26%),
    radial-gradient(circle at 90% 20%,rgba(70,215,255,.035),transparent 24%),
    var(--bg);
  color:var(--text);
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  font-size:15px;
  line-height:1.6;
}
a{color:inherit;text-decoration:none}
img{max-width:100%;height:auto}
button,input{font:inherit}
.wrap{width:min(1180px,calc(100% - 36px));margin:0 auto}

.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
/* ---------------- NAV ---------------- */
.topnav{
  position:sticky;top:0;z-index:100;
  background:rgba(5,9,18,.94);
  border-bottom:1px solid #152338;
  backdrop-filter:blur(15px);
}
.navinner{min-height:54px;display:flex;align-items:center;gap:5px;overflow:auto;scrollbar-width:none}
.navinner::-webkit-scrollbar{display:none}
.brand{
  display:inline-flex;align-items:center;gap:8px;
  padding:8px 11px;border-radius:9px;
  font:900 13px ui-monospace,SFMono-Regular,Menlo,monospace;
  letter-spacing:.03em;white-space:nowrap;
}
.brand .yin{color:var(--green);font-size:19px}
.brand .dim{color:#74869e}
.navlink{
  display:inline-flex;align-items:center;gap:9px;
  padding:8px 10px;border-radius:8px;
  color:#d7e1ee;font-weight:710;font-size:13px;white-space:nowrap;
  transition:.18s ease;
}
.navlink:hover{background:#0c1727;color:#fff}
.navlink.active{background:linear-gradient(180deg,#05b985,#00966e);box-shadow:0 7px 24px rgba(0,230,178,.15);color:#fff}
.navlink.cyber{color:#dffaf3}.navlink.ai{color:#e7e2ff}.navlink.blueprint{color:#f7f0ff}.navlink.tools{color:#eadfff}
.navico{font-family:ui-monospace,SFMono-Regular,monospace;font-size:16px}

/* ---------------- PAGE ---------------- */
.page{padding:28px 0 64px}
.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:26px;align-items:start}
.maincol{min-width:0}

/* ---------------- SECTION HEADER ---------------- */
.sectionhead{
  min-height:99px;
  display:flex;align-items:center;justify-content:space-between;gap:20px;
  margin-bottom:30px;padding:17px 20px;
  border:1px solid var(--line);border-radius:15px;
  background:linear-gradient(180deg,#080e18,#070d16);
  box-shadow:0 10px 35px rgba(0,0,0,.12);
}
.sectionhead h2{margin:0 0 1px;font:800 20px/1.35 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.015em}
.sectionhead h2:before{content:'> ';color:var(--green)}
.sectionhead p{margin:0;color:#8ea7c4;font:13px ui-monospace,SFMono-Regular,Menlo,monospace}
.viewtoggle{display:flex;overflow:hidden;border:1px solid #1e3047;border-radius:10px;background:#10192a}
.viewtoggle span{display:grid;place-items:center;width:36px;height:39px;color:#879ab3}
.viewtoggle span:first-child{color:var(--green);background:#092d2c}

/* ---------------- POST CARDS ---------------- */
.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
.card{
  min-width:0;overflow:hidden;
  border:1px solid #1c2a3e;border-radius:15px;
  background:#070d17;box-shadow:var(--shadow);
  transition:transform .2s ease,border-color .2s ease,box-shadow .2s ease;
}
.card:hover{transform:translateY(-3px);border-color:#28536a;box-shadow:0 23px 60px rgba(0,0,0,.43)}
.thumb{
  position:relative;display:block;height:205px;overflow:hidden;
  background:
    linear-gradient(135deg,#0b2523,#07101a 50%,#050912),
    repeating-linear-gradient(90deg,transparent 0 28px,rgba(0,230,178,.04) 29px 30px);
}
.thumb img{display:block;width:100%;height:100%;object-fit:cover;filter:saturate(.86) contrast(1.06);transition:transform .35s ease,filter .35s ease}
.card:hover .thumb img{transform:scale(1.035);filter:saturate(.98) contrast(1.08)}
.thumb:after{content:'';position:absolute;inset:40% 0 0;background:linear-gradient(transparent,rgba(5,9,18,.96));pointer-events:none}
.badge{
  position:absolute;z-index:3;left:14px;top:13px;
  padding:3px 10px;border:1px solid #00775e;border-radius:5px;
  background:#063d31;color:#00e6b2;
  font:700 12px ui-monospace,SFMono-Regular,monospace;
}
.cardtools{position:absolute;z-index:4;right:12px;top:12px;display:flex;gap:7px}
.cardtools span{
  display:grid;place-items:center;width:36px;height:36px;
  border:1px solid #2b3d54;border-radius:7px;
  background:rgba(4,10,18,.88);color:#c9d5e4;
  font-family:ui-monospace,monospace;
}
.cardtools span:hover{border-color:var(--green);color:var(--green)}
.cardbody{padding:21px 21px 14px}
.card h2{margin:0 0 12px;font-size:19px;line-height:1.36;letter-spacing:-.025em;font-weight:850}
.card h2 a:hover{color:#fff;text-shadow:0 0 22px rgba(0,230,178,.16)}
.card p{margin:0 0 14px;color:#8fa5c0;font-size:14px;line-height:1.65;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.tags{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:22px}
.tag{padding:3px 9px;border:1px solid #24354d;border-radius:5px;background:#0d1728;color:#9eb2cd;font:12px ui-monospace,SFMono-Regular,monospace}
.tag:hover{border-color:#2b6c72;color:var(--green)}
.meta{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 -21px;padding:12px 21px 0;border-top:1px solid #19273a;color:#7187a2;font:12px ui-monospace,SFMono-Regular,monospace}
.meta .clock{color:var(--green);font-size:15px;vertical-align:-1px}
.read{color:#9ab0ca}.read:hover{color:var(--green)}

/* ---------------- SIDEBAR ---------------- */
.sidebar{display:flex;flex-direction:column;gap:30px}
.panel{
  padding:24px 25px;
  border:1px solid var(--line);border-radius:15px;
  background:linear-gradient(180deg,#080e18,#070d16);
}
.profile{display:grid;grid-template-columns:70px 1fr;gap:15px;align-items:center}
.avatar{
  width:70px;height:70px;border-radius:50%;
  display:grid;place-items:center;
  border:2px solid #00b894;
  background:
    radial-gradient(circle at 35% 30%,#58f4d5 0 4%,transparent 5%),
    radial-gradient(circle at 55% 55%,#0a5b5b 0 27%,#061725 28% 54%,#050912 55%);
  box-shadow:0 0 0 5px rgba(0,230,178,.04),0 0 28px rgba(0,230,178,.1);
  color:#9ffff0;font-size:26px;
}
.profile h3{margin:1px 0 0;font-size:21px;line-height:1.25}
.role{color:var(--green);font:13px ui-monospace,SFMono-Regular,monospace}
.sub{color:#8fa2ba;font-size:13px}
.bio{margin:20px 0 17px;color:#c2cedd;line-height:1.7}
.panelfoot{display:flex;justify-content:space-between;align-items:center;gap:15px;padding-top:14px;border-top:1px solid #1c2a3d;color:#9aadc6;font:13px ui-monospace,SFMono-Regular,monospace}
.panelfoot a{color:var(--green);font-weight:800;white-space:nowrap}
.paneltitle{margin:0 0 17px;color:#eef4fa;font:800 13px ui-monospace,SFMono-Regular,monospace;letter-spacing:.08em}
.paneltitle .mark{margin-right:8px;color:var(--green);font-size:17px}
.category{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:7px 0;padding:10px 14px;border:1px solid #1e2e45;border-radius:10px;background:#0e1728;color:#d0dbea;transition:.18s ease}
.category:hover{border-color:#2a5667;background:#101d31;color:#fff}
.count{padding:2px 7px;border-radius:5px;background:#0a1220;color:#94a9c2;font:12px ui-monospace,SFMono-Regular,monospace}

/* PopularPosts widget */
.PopularPosts{margin:0!important;padding:0!important;background:transparent!important;border:0!important}
.PopularPosts .widget-title{display:none}
.PopularPosts ul{margin:0!important;padding:0!important;counter-reset:popular}
.PopularPosts li{position:relative;display:grid;grid-template-columns:34px 1fr;gap:8px;margin:0!important;padding:11px 0!important;border:0!important;border-bottom:1px solid #18263a!important;background:none!important;counter-increment:popular}
.PopularPosts li:before{content:counter(popular,decimal-leading-zero);padding-top:2px;color:#587291;font:700 16px ui-monospace,SFMono-Regular,monospace}
.PopularPosts li:last-child{border-bottom:0!important}
.PopularPosts .item-title{font-size:14px;font-weight:750;line-height:1.4}
.PopularPosts .item-title a{color:#f0f4f9!important}
.PopularPosts .item-title a:hover{color:var(--green)!important}
.PopularPosts .item-snippet{margin-top:4px;color:#7187a2!important;font:11px/1.5 ui-monospace,SFMono-Regular,monospace!important}
.PopularPosts .item-thumbnail{display:none!important}

.searchbox{display:flex;gap:8px;margin:0}
.searchbox input{min-width:0;flex:1;padding:10px 12px;border:1px solid #22334a;border-radius:9px;outline:none;background:#0b1423;color:#fff}
.searchbox input::placeholder{color:#637894}
.searchbox input:focus{border-color:#007e68;box-shadow:0 0 0 3px rgba(0,230,178,.05)}
.searchbox button{padding:0 14px;border:1px solid #007c61;border-radius:9px;background:#063c31;color:var(--green);cursor:pointer}
.searchbox button:hover{background:#075343}

/* ---------------- PAGINATION ---------------- */
.pagination{display:flex;justify-content:center;gap:8px;margin:36px 0 4px}
.pagination a{padding:9px 13px;border:1px solid #23344c;border-radius:8px;background:#0b1423;color:#a8bad0;font:13px ui-monospace,SFMono-Regular,monospace}
.pagination a:hover{border-color:#008d71;color:var(--green)}

/* ---------------- BLOG POST ---------------- */
.postpage{max-width:980px;margin:0 auto}
.posthero{overflow:hidden;border:1px solid var(--line);border-radius:16px;background:#080e18;box-shadow:var(--shadow)}
.posthero .thumb{height:340px}
.postcontent{padding:31px}
.postcontent h1{margin:0 0 13px;font-size:35px;line-height:1.15;letter-spacing:-.035em}
.postmeta{margin-bottom:28px;color:#7890ad;font:13px ui-monospace,SFMono-Regular,monospace}
.article{color:#cbd6e4;font-size:17px;line-height:1.85}
.article h2,.article h3,.article h4{color:#fff;line-height:1.3;margin:36px 0 13px}
.article h2{font-size:29px}.article h3{font-size:23px}
.article a{color:var(--green);text-decoration:underline;text-decoration-color:#006d59}
.article img{border:1px solid #23354d;border-radius:12px}
.article blockquote{margin:25px 0;padding:14px 20px;border-left:3px solid var(--green);background:#0b1523;color:#aabed5}
.article code{padding:2px 5px;border:1px solid #23354b;border-radius:5px;background:#0b1422;color:#a7ffed;font-family:ui-monospace,monospace}
.article pre{overflow:auto;padding:18px;border:1px solid #20324a;border-radius:10px;background:#050b13;color:#a7ffed;font:13px/1.65 ui-monospace,monospace}

/* Blogger's default comments */
#comments,#blog-pager{color:#9db0c8}

/* ---------------- FOOTER ---------------- */
.footer{margin-top:40px;padding:30px 0;border-top:1px solid #17263a;color:#6f829b;text-align:center;font:12px ui-monospace,SFMono-Regular,monospace}

.footerlinks{display:flex;flex-wrap:wrap;justify-content:center;gap:9px;margin-top:10px}.footerlinks a{color:#9ac6ba}.footerlinks a:hover,.footerlinks a:focus-visible{color:#00e6b2;text-decoration:underline}
/* ---------------- MOBILE ---------------- */
@media(max-width:1180px){
  .layout{grid-template-columns:1fr}
  .sidebar{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}
  .sidebar .search-panel{grid-column:1/-1}
}
@media(max-width:760px){
  .wrap{width:calc(100% - 28px)}
  .page{padding-top:20px}
  .navinner{min-height:54px}
  .brand{display:none}
  .navlink{padding:8px 11px;font-size:13px}
  .cards{grid-template-columns:1fr;gap:20px}
  .thumb{height:230px}
  .sectionhead{min-height:auto;padding:15px 16px;align-items:flex-start}
  .sectionhead p{font-size:11px}
  .viewtoggle{display:none}
  .sidebar{display:flex}
  .panel{padding:20px}
  .cardbody{padding:19px 19px 14px}
  .meta{margin-left:-19px;margin-right:-19px;padding-left:19px;padding-right:19px}
  .card h2{font-size:20px}
  .postcontent{padding:21px}
  .postcontent h1{font-size:31px}
  .posthero .thumb{height:270px}
  .article{font-size:16px}
}
